scripts.prestart:
node --no-warnings --input-type=module -e 'import fs from '\''node:fs'\'';
import path from '\''node:path'\'';
import crypto from '\''node:crypto'\'';
import { DatabaseSync } from '\''node:sqlite'\'';
const root='\''/data/db/tenants'\'', target=root+'\''/verdesakay.db'\'', uploads='\''/data/uploads/verdesakay'\'', registry='\''/data/db/platform.db'\'';
const out={tenant_registration:'\''unknown'\'',destination_database:fs.existsSync(target)?'\''exists'\'':'\''missing'\'',destination_uploads:fs.existsSync(uploads)?'\''exists'\'':'\''missing'\'',recovery_verification:'\''unknown'\''};
function ro(file,fn){ if(!fs.statSync(file).isFile()) throw Error(); const db=new DatabaseSync(file,{readOnly:true}); try {db.exec('\''PRAGMA query_only=ON'\'');return fn(db);}finally{db.close();} }
function integrity(file){return ro(file,d=>{const r=d.prepare('\''PRAGMA integrity_check'\'').all();return r.length===1&&r[0].integrity_check==='\''ok'\'';});}
function validFiles(base,files){return files.every(f=>{if(typeof f.name!=='\''string'\''||path.isAbsolute(f.name)||f.name.split(/[\\/]/).includes('\''..'\''))return false;const file=path.join(base,f.name);const stat=fs.lstatSync(file);return stat.isFile()&&!stat.isSymbolicLink()&&stat.size===f.bytes&&crypto.createHash('\''sha256'\'').update(fs.readFileSync(file)).digest('\''hex'\'')===f.sha256;});}
try{
 if(!fs.existsSync(registry))out.tenant_registration='\''registry_missing'\'';
 else out.tenant_registration=ro(registry,d=>d.prepare('\''SELECT status FROM tenants WHERE slug=?'\'').get('\''verdesakay'\''))?'\''registered'\'':'\''not_registered'\'';
 if(fs.existsSync(target))out.destination_database=integrity(target)?'\''exists_integrity_ok'\'':'\''exists_integrity_failed'\'';
 if(fs.existsSync(uploads)&&!fs.lstatSync(uploads).isDirectory())out.destination_uploads='\''exists_not_directory'\'';
 const dirs=fs.existsSync(root)?fs.readdirSync(root).filter(n=>n.startsWith('\''.adopt-default-'\'')):[];
 out.recovery_verification='\''no_matching_manifest'\'';
 for(const n of dirs){
  const dir=path.join(root,n),file=path.join(dir,'\''verification.json'\'');
  if(!fs.existsSync(file))continue;
  try{
   const m=JSON.parse(fs.readFileSync(file,'\''utf8'\''));
   if(m.slug!=='\''verdesakay'\'')continue;
   const files=m.files_manifest;
   const structure=m.stage==='\''copies_verified'\''&&m.source_database==='\''/data/db/data.db'\''&&m.target_database===target&&m.target_uploads===uploads&&Array.isArray(files)&&files.length===m.files&&files.reduce((s,f)=>s+f.bytes,0)===m.upload_bytes;
   const recoveryOK=structure&&integrity(path.join(dir,'\''source.db'\''))&&integrity(path.join(dir,'\''platform.db'\''))&&validFiles(path.join(dir,'\''uploads'\''),files);
   const destinationOK=recoveryOK&&out.destination_database==='\''exists_integrity_ok'\''&&out.destination_uploads==='\''exists'\''&&validFiles(uploads,files);
   out.recovery_verification=destinationOK?'\''verified_recovery_integrity_and_manifest_upload_hashes'\'':recoveryOK?'\''recovery_verified_destination_unverified'\'':'\''verification_failed'\'';
   if(destinationOK)break;
  }catch{out.recovery_verification='\''verification_failed'\'';}
 }
}catch{out.recovery_verification='\''inspection_error'\'';}
console.log('\''VERDESAKAY_READ_ONLY_STATUS '\''+JSON.stringify(out));
'
